parameters.inputSchema:
{
  "type":"object",
  "properties":{
    "thumbnail_prompt":{
       "type":"string",
       "description":"the image prompt to generate the thumbnail image"
    }
  },
  "required":[
    "thumbnail_prompt"
  ]
}

{
  "type":"object",
  "properties":{
    "title":{
       "type":"string",
       "description":"the title of the video idea"
    },
    "visual":{
       "type":"string",
       "description":"the visual characteristics of the video"
    }
  },
  "required":[
    "title",
    "visual"
  ]
}

{
  "type":"object",
  "properties": {
      "music_prompt": {
          "type": "string",
          "description": "the music prompt for music generation"
      },
      "image_prompt": {
          "type": "string",
          "description": "the image prompt to generate the seed image for the video generation"
      },
      "video_prompt": {
          "type": "string",
          "description": "the video prompt to generate the looping video"
      }
  },
  "required": [
      "music_prompt",
      "image_prompt",
      "video_prompt"
  ]
}
